export const groups: Group[] = (raw as { slug: string; products: Product[] }[])
  .filter((g) => meta[g.slug])
  .map((g) => ({ slug: g.slug, ...meta[g.slug], products: g.products }));

export const productCount = groups.reduce((n, g) => n + g.products.length, 0);

export const productSlug = (name: string) =>
  name
    .toLowerCase()
    .replace(/\(.*?\)/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");

/** "Caustic Soda Lye (NaOH)" -> { base: "Caustic Soda Lye", formula: "NaOH" } */
export function splitName(name: string) {
  const m = name.match(/^(.*?)\s*\((.+)\)\s*(.*)$/);
  if (!m) return { base: name, formula: "" };
  return { base: (m[1] + (m[3] ? " " + m[3] : "")).trim(), formula: m[2].replace(/\)\s*\(/g, " · ") };
}
